// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(this));
        vm.assume(caller != c.owner());
        bound(amount, 1, address(this).balance);
        vm.deal(address(c), amount);
        uint256 beforeBal = address(c).balance;
        bool ok;
        vm.prank(caller);
        try c.sendMoney(address(0xbeef), amount) { ok = true; } catch { ok = false; }
        assertTrue(ok ? address(c).balance < beforeBal : address(c).balance == beforeBal);
    }
}
